select ba.id, ba.username, ba.avatar, ba.nickname, ba.sex, ba.phone, ba.email, ba.status, ba.create_time from bedrock_admin ba where ba.is_deleted = 0
and ba.username like concat('%',#{params.username},'%')
and ba.nickname like concat('%',#{params.nickname},'%')
and ba.status = #{params.status}
and ba.phone like concat('%',#{params.phone},'%')
and ba.email like concat('%',#{params.email},'%')
and ba.sex = #{params.sex}
and exists(select 1 from bedrock_admin_dept where admin_id = ba.id and dept_id = #{params.deptId})
and exists(select 1 from bedrock_admin_role where admin_id = ba.id and role_id = #{params.roleId})
and not exists(select 1 from bedrock_admin_role bar inner join bedrock_role br on bar.role_id = br.id where admin_id = ba.id and br.role_alias in (
#{alias}
)) order by ba.create_time desc

select ba.id, ba.username, ba.nickname, ba.sex, ba.phone, ba.email, ba.status, ba.remark, bd.dept_name, br.role_name from bedrock_admin ba left join bedrock_admin_dept bad on ba.id = bad.admin_id left join bedrock_dept bd on bd.id = bad.dept_id left join bedrock_admin_role bar on ba.id = bar.admin_id left join bedrock_role br on bar.role_id = br.id where ba.is_deleted = 0
and ba.username like concat('%',#{params.username},'%')
and ba.nickname like concat('%',#{params.nickname},'%')
and ba.status = #{params.status}
and ba.phone like concat('%',#{params.phone},'%')
and ba.email like concat('%',#{params.email},'%')
and ba.sex = #{params.sex}
and exists(select 1 from bedrock_admin_dept where admin_id = ba.id and dept_id = #{params.deptId})
and exists(select 1 from bedrock_admin_role where admin_id = ba.id and role_id = #{params.roleId})
and not exists(select 1 from bedrock_admin_role bar inner join bedrock_role br on bar.role_id = br.id where admin_id = ba.id and br.role_alias in (
#{alias}
)) order by ba.create_time desc
